import sys

def lcs_len(s1: str, s2: str) -> int:
    if len(s1) < len(s2):
        s1, s2 = s2, s1
    dp = [0] * (len(s2) + 1)
    for c1 in s1:
        prev = 0
        for j, c2 in enumerate(s2):
            temp = dp[j + 1]
            if c1 == c2:
                dp[j + 1] = prev + 1
            elif dp[j] > dp[j + 1]:
                dp[j + 1] = dp[j]
            prev = temp
    return dp[-1]

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        s1 = lines[0] if lines else ""
        s2 = ""
    else:
        s1, s2 = lines[0], lines[1]
    print(lcs_len(s1, s2))

if __name__ == "__main__":
    main()
